function spawnSpots(z,cx,cy,r0,r1,n){const sx=Math.floor(cx),sy=Math.floor(cy),lim=Math.ceil(r1*1.6)+1,D=bfs(z,sx,sy,lim),good=[],ok=[],R=Math.ceil(r1)+1;
  for(let y=Math.max(0,sy-R);y<=Math.min(z.h-1,sy+R);y++)for(let x=Math.max(0,sx-R);x<=Math.min(z.w-1,sx+R);x++){const v=D[y*z.w+x];if(v<1||v>lim)continue;const e=Math.hypot(x+.5-cx,y+.5-cy);if(e>r1+.5)continue;
    if(p&&Math.hypot(x+.5-p.x,y+.5-p.y)<1.2)continue;const L=losClear(z,cx,cy,x+.5,y+.5);if(e>=r0&&L)good.push([x,y]);else ok.push([x,y,(L?0:10)+Math.abs(e-r0)]);}
  for(let i=good.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[good[i],good[j]]=[good[j],good[i]];}
  ok.sort((a,b)=>a[2]-b[2]);const out=good.slice(0,n);for(const c of ok){if(out.length>=n)break;if(c[2]<10)out.push([c[0],c[1]]);}return out;}
