function recolorZone(z){const st=z.style,f=palOf(st).floor;for(let y=0;y<z.h;y++)for(let x=0;x<z.w;x++){const i=y*z.w+x;if(!z.fc[i])continue;let n=(Math.sin(x*12.9898+y*78.233)*43758.5453)%1;n=(n<0?n+1:n)*14-7;
  let r=f[0]+n,g=f[1]+n,b=f[2]+n;if(st==='crypt'&&(x+y)%2)r-=4,g-=4,b-=3;z.fc[i]=`rgb(${r|0},${g|0},${b|0})`;}freeCv(z);}
