/* v5.85 : chapelle profanée et tombe fraîche */
const PRAYERS=[{k:'force',n:'Prière de la Force',d:'+30 % de dégâts dans cette zone'},{k:'garde',n:'Prière de la Garde',d:'−25 % de dégâts reçus dans cette zone'},{k:'richesse',n:'Prière de la Richesse',d:'+60 % de butin dans cette zone'}];
